DECLARE @BitmapOrder TINYINT = 4

UPDATE cs
SET cs.bitmapHasSynced = dbo.f_GenerateProductStatus(bitmapHasSynced, @BitmapOrder, 1)
FROM [dbo].[CustProductStatus] cs WITH(ROWLOCK,UPDLOCK)
WHERE custid IN (24167640,24168580,24168772,24172343,24170125,24170084,24174559,24170717,24169923,24170086,24169993,24170075,24178930,24174382,24177637,24177783,
